function jparse(s,f){ try{return JSON.parse(s)}catch(_){return f} }
let best=jparse(localStorage.getItem('ql_best'),null)||{score:0,stage:1};
function saveBest(){ try{localStorage.setItem('ql_best',JSON.stringify(best))}catch(_){} }
function updBestLine(){ document.getElementById('bestLine').textContent = best.score>0 ? TX('내 최고 '+best.score.toLocaleString()+'점 · 스테이지 '+best.stage, 'Best '+best.score.toLocaleString()+' pts · stage '+best.stage) : ''; }
let collected=new Set(jparse(localStorage.getItem('ql_coll'),[])||[]);
function saveColl(){ try{localStorage.setItem('ql_coll',JSON.stringify([...collected]))}catch(_){} }

