function applyI18n(){
  document.documentElement.lang = LANG;
  document.querySelectorAll('[data-i18n]').forEach(el=>{ const v=I18N[el.dataset.i18n]; if(v) el.innerHTML=v[LANG]; });
  const lb=document.getElementById('langBtn'); if(lb) lb.textContent = LANG==='en'?'🌐 한국어':'🌐 English';
  const db=document.getElementById('diffBadge'); if(db) db.textContent = running ? (dLabel(cfg)+' '+stage+'/'+STAGE_MAX) : dLabel(DIFF[pendingDiff]);
  if(typeof updBestLine==='function') updBestLine();
  if(typeof updDiffDesc==='function') updDiffDesc();
}
function setLang(l){ LANG=l; try{localStorage.setItem('ql_lang',l)}catch(_){} quizPool=[]; applyI18n(); }
// ---- daily tarot ----
function todayStr(){ const d=new Date(); return d.getFullYear()+'-'+(d.getMonth()+1)+'-'+d.getDate(); }
function dailyCard(){ const s=todayStr(); let h=5381; for(let i=0;i<s.length;i++){ h=((h*33)^s.charCodeAt(i))>>>0; } return DECK[h%DECK.length]; }
function openDaily(){ const c=dailyCard(), key='ql_daily', fresh=(localStorage.getItem(key)!==todayStr());
  document.getElementById('dlCard').style.background='linear-gradient(180deg,'+c.c0+','+c.c1+')';
  document.getElementById('dlNum').textContent = c.arcana==='major'? toRoman(c.num) : (c.num<=10?String(c.num):'');
  document.getElementById('dlEmoji').textContent=c.emoji;
  document.getElementById('dlName').textContent=cName(c);
  document.getElementById('dlMean').textContent='"'+cFortune(c)+'"';
  let add;
  if(fresh){ try{localStorage.setItem(key,todayStr())}catch(_){}
    if(!collected.has(c.id)){ collected.add(c.id); saveColl(); add=TX('✨ 도감에 새 카드 추가!',"✨ New card added to your deck!"); }
    else add=TX('오늘의 카드를 확인했어요',"You've drawn today's card"); }
  else add=TX('오늘은 이미 뽑았어요',"Already drawn today");
  document.getElementById('dlAdd').textContent=add;
  show('dailyOv');
}

