function toRoman(n){ if(n===0)return '0'; const m=[[10,'X'],[9,'IX'],[5,'V'],[4,'IV'],[1,'I']]; let r='',x=n; for(const p of m){while(x>=p[0]){r+=p[1];x-=p[0];}} return r; }
function cardFrame(g){let W=g.canvas.width,H=g.canvas.height, m=Math.round(W*0.04);
  g.strokeStyle='rgba(255,240,200,.9)';g.lineWidth=Math.max(8,W*0.028);g.strokeRect(m,m,W-2*m,H-2*m);
  g.strokeStyle='rgba(255,240,200,.45)';g.lineWidth=2.5;g.strokeRect(m*2,m*2,W-4*m,H-4*m);
  g.fillStyle='rgba(255,240,200,.9)'; const d=W*0.026;
  [[m,m],[W-m,m],[m,H-m],[W-m,H-m]].forEach(p=>{g.save();g.translate(p[0],p[1]);g.rotate(Math.PI/4);g.fillRect(-d,-d,2*d,2*d);g.restore();});}
function drawCard(g,card){
  const W=g.canvas.width,H=g.canvas.height;
  let bg=g.createLinearGradient(0,0,0,H); bg.addColorStop(0,card.c0);bg.addColorStop(1,card.c1);
  g.fillStyle=bg;g.fillRect(0,0,W,H);
  g.globalAlpha=0.08;g.fillStyle='#fff';for(let i=0;i<44;i++){g.beginPath();g.arc((i*97)%W,(i*61)%H,3,0,7);g.fill();}g.globalAlpha=1;
  cardFrame(g);
  g.textAlign='center';g.textBaseline='middle';
  g.font='118px serif'; g.fillText(card.emoji, W/2, H*0.45);
  g.fillStyle='rgba(255,255,255,.95)';
  g.font='bold 24px sans-serif';
  const top = card.arcana==='major'? toRoman(card.num) : (card.num<=10? String(card.num) : '');
  if(top) g.fillText(top, W/2, H*0.15);
  g.font='bold 22px sans-serif'; g.fillText(cName(card), W/2, H*0.85);
  g.textBaseline='alphabetic';
}
let curCard=DECK[0];
