function show(id){ hideAll(); document.getElementById(id).classList.remove('hide'); }
function hideAll(){ ['startOv','quizOv','clearOv','overOv','dexOv','helpOv','cardOv','dailyOv'].forEach(x=>document.getElementById(x).classList.add('hide')); }
function goHome(){ running=false; document.getElementById('diffBadge').classList.add('hide'); updBestLine(); show('startOv'); }

// ---- skills ----
function vibrate(p){ try{ navigator.vibrate && navigator.vibrate(p); }catch(_){} }
let spinning=false;
function applySkill(k){
  if(k==='shield'){ shieldOn=true; }
  else if(k==='slow'){ slowT=Math.max(slowT,5000); }
  else if(k==='freeze'){ freezeT=Math.max(freezeT,2000); }
  else if(k==='thunder'){ freezeT=Math.max(freezeT,3000); invuln=Math.max(invuln,50); }
  const m=SKILL_META[k]; toast((k==='thunder'?TX('⚡★레어★ ','⚡★RARE★ '):TX('🎁 랜덤: ','🎁 Random: '))+m[0]+' '+TX(m[1],m[2]||m[1])+'!'); vibrate(k==='thunder'?[25,40,60]:30);
}
function useRandomSkill(){ if(!running||skillCharges<=0||spinning) return;
  skillCharges--; updSkills(); spinning=true;
  const k = rnd()<0.06 ? 'thunder' : ['shield','slow','freeze'][Math.floor(rnd()*3)];   // 순수 랜덤(레어 6%)
  const bx=document.getElementById('skillBx'), faces=['🛡️','❄️','⏸️','⚡'];
  let t=0, delay=45;
  const spin=()=>{ bx.textContent=faces[Math.floor(rnd()*faces.length)]; t+=delay; delay*=1.15;
    if(t<520){ setTimeout(spin,delay); }
    else { bx.textContent=SKILL_META[k][0]; applySkill(k); setTimeout(()=>{ bx.textContent='🎁'; },800); spinning=false; } };
  spin();
}
document.getElementById('skillBox').addEventListener('click',e=>{e.preventDefault();useRandomSkill();});

// ---- difficulty ----
function updDiffDesc(){ document.getElementById('diffDesc').textContent=dDesc(DIFF[pendingDiff]); }
document.querySelectorAll('#diffSel button').forEach(b=>{ b.addEventListener('click',()=>{
  pendingDiff=b.dataset.d; document.querySelectorAll('#diffSel button').forEach(x=>x.classList.toggle('sel',x===b)); updDiffDesc();
  document.getElementById('diffBadge').textContent=DIFF[pendingDiff].label; }); });

// ---- movement (8방향/대각선 지원) ----
function press(d){ const i=held.indexOf(d); if(i>=0)held.splice(i,1); held.push(d); }
function release(d){ const i=held.indexOf(d); if(i>=0)held.splice(i,1); }
function vec4(dx,dy){ if(Math.abs(dx)+Math.abs(dy)<12) return null;
  return Math.abs(dx)>Math.abs(dy) ? {dx:dx>0?1:-1,dy:0} : {dx:0,dy:dy>0?1:-1}; }

// 플로팅 원형 조이스틱: 조준칸 아무 곳이나 눌러 생성 → 미는 방향(8방향)으로 이동 → 떼면 멈춤
const joyzone=document.getElementById('joyzone'), joyBase=document.getElementById('joyBase'), joyStick=document.getElementById('joyStick');
let joyId=null, joyOrigin=null;
joyzone.addEventListener('pointerdown',e=>{ if(!running) return; e.preventDefault(); joyId=e.pointerId;
  const r=joyzone.getBoundingClientRect(); joyOrigin={x:e.clientX,y:e.clientY};
  joyBase.style.left=(e.clientX-r.left-48)+'px'; joyBase.style.top=(e.clientY-r.top-48)+'px'; joyBase.classList.add('on');
  joyStick.style.left='26px'; joyStick.style.top='26px'; joyzone.classList.add('active');
  try{joyzone.setPointerCapture(e.pointerId)}catch(_){} });
joyzone.addEventListener('pointermove',e=>{ if(joyId===null||e.pointerId!==joyId||!joyOrigin) return;
  const dx=e.clientX-joyOrigin.x, dy=e.clientY-joyOrigin.y, cl=Math.min(Math.hypot(dx,dy)||1,34), a=Math.atan2(dy,dx);
  joyStick.style.left=(26+Math.cos(a)*cl)+'px'; joyStick.style.top=(26+Math.sin(a)*cl)+'px';
  moveVec=vec4(dx,dy); });
const joyEnd=e=>{ if(joyId!==null&&e.pointerId!==joyId) return; joyId=null; joyOrigin=null; joyBase.classList.remove('on'); joyzone.classList.remove('active'); moveVec=null; };
joyzone.addEventListener('pointerup',joyEnd); joyzone.addEventListener('pointercancel',joyEnd);

const KEYMAP={arrowup:'up',arrowdown:'down',arrowleft:'left',arrowright:'right',w:'up',s:'down',a:'left',d:'right'};
window.addEventListener('keydown',e=>{ const d=KEYMAP[e.key.toLowerCase()]; if(d){e.preventDefault(); press(d);} });
window.addEventListener('keyup',e=>{ const d=KEYMAP[e.key.toLowerCase()]; if(d){release(d);} });

// 게임화면 드래그(스와이프, 8방향) — 재중심
let ptOrigin=null;
cv.addEventListener('pointerdown',e=>{ if(!running) return; e.preventDefault(); ptOrigin={x:e.clientX,y:e.clientY}; try{cv.setPointerCapture(e.pointerId)}catch(_){} });
cv.addEventListener('pointermove',e=>{ if(!ptOrigin) return; const dx=e.clientX-ptOrigin.x, dy=e.clientY-ptOrigin.y; if(Math.abs(dx)+Math.abs(dy)<16) return;
  moveVec=vec4(dx,dy); ptOrigin={x:e.clientX,y:e.clientY}; });
const endSwipe=()=>{ ptOrigin=null; moveVec=null; };
cv.addEventListener('pointerup',endSwipe); cv.addEventListener('pointercancel',endSwipe); cv.addEventListener('pointerleave',endSwipe);

